-- ----------------------------------------------------------------------------
-- Reasoning: The one world the rules reason over, and the switch of each of her five rules. Every table links here, so each rule's switch is one lookup away from the field it gates, and every count of the world rolls up here.
-- ----------------------------------------------------------------------------
CREATE TABLE reasoning (
  reasoning_id                        TEXT                 PRIMARY KEY,         -- Key of the world.
  label                               TEXT                ,                     -- The world's name.
  inverse_is_on                       BOOLEAN             ,                     -- Inverse rule: a parent link also gives a child link between the same two people (isChildOf, the inverse of isParentOf).
  symmetric_is_on                     BOOLEAN             ,                     -- Symmetric rule: a spouse link or a friend link holds for both people.
  chain_is_on                         BOOLEAN             ,                     -- Property chain: a parent of a parent is a grandparent (isParentOf then isParentOf gives isGrandparentOf).
  domain_range_is_on                  BOOLEAN             ,                     -- Domain and range: whoever attends something, or has a grade level or a role, is a Person; whatever is attended is a School.
  disjoint_is_on                      BOOLEAN                                   -- Disjoint: no one is both the parent and the spouse of the same person (isParentOf is disjoint with isSpouseOf).
);
COMMENT ON TABLE reasoning IS 'The one world the rules reason over, and the switch of each of her five rules. Every table links here, so each rule''s switch is one lookup away from the field it gates, and every count of the world rolls up here.';
COMMENT ON COLUMN reasoning.reasoning_id IS 'Key of the world.';
COMMENT ON COLUMN reasoning.label IS 'The world''s name.';
COMMENT ON COLUMN reasoning.inverse_is_on IS 'Inverse rule: a parent link also gives a child link between the same two people (isChildOf, the inverse of isParentOf).';
COMMENT ON COLUMN reasoning.symmetric_is_on IS 'Symmetric rule: a spouse link or a friend link holds for both people.';
COMMENT ON COLUMN reasoning.chain_is_on IS 'Property chain: a parent of a parent is a grandparent (isParentOf then isParentOf gives isGrandparentOf).';
COMMENT ON COLUMN reasoning.domain_range_is_on IS 'Domain and range: whoever attends something, or has a grade level or a role, is a Person; whatever is attended is a School.';
COMMENT ON COLUMN reasoning.disjoint_is_on IS 'Disjoint: no one is both the parent and the spouse of the same person (isParentOf is disjoint with isSpouseOf).';

-- ----------------------------------------------------------------------------
-- Portraits: The picture of each individual, linked from its Fandom page (never downloaded).
-- ----------------------------------------------------------------------------
CREATE TABLE portraits (
  portrait_id                         TEXT                 PRIMARY KEY,         -- Key of the portrait: the short name the page files it under.
  display_name                        TEXT                ,                     -- The name on the portrait's Fandom page.
  page                                TEXT                ,                     -- The Fandom page credited for the portrait.
  image                               TEXT                ,                     -- The original Fandom image.
  crop                                TEXT                ,                     -- The crop as an SVG viewBox: x y width height.
  width                               INTEGER             ,                     -- The original image's width in pixels.
  height                              INTEGER             ,                     -- The original image's height in pixels.
  sort_order                          INTEGER                                   -- Position in the credits.
);
COMMENT ON TABLE portraits IS 'The picture of each individual, linked from its Fandom page (never downloaded).';
COMMENT ON COLUMN portraits.portrait_id IS 'Key of the portrait: the short name the page files it under.';
COMMENT ON COLUMN portraits.display_name IS 'The name on the portrait''s Fandom page.';
COMMENT ON COLUMN portraits.page IS 'The Fandom page credited for the portrait.';
COMMENT ON COLUMN portraits.image IS 'The original Fandom image.';
COMMENT ON COLUMN portraits.crop IS 'The crop as an SVG viewBox: x y width height.';
COMMENT ON COLUMN portraits.width IS 'The original image''s width in pixels.';
COMMENT ON COLUMN portraits.height IS 'The original image''s height in pixels.';
COMMENT ON COLUMN portraits.sort_order IS 'Position in the credits.';

-- ----------------------------------------------------------------------------
-- Individuals: Every individual of the world (owl:Thing). What is said about one individual alone is a column of its row: its age, the place it attends, whether it is asserted to be a Person or a School. Its current grade level and role come from their records. Class membership is a formula, not a table, because it is concluded: no one stated that South Park Elementary is a School.
-- ----------------------------------------------------------------------------
CREATE TABLE individuals (
  individual_id                       TEXT                 PRIMARY KEY,         -- Key of the individual.
  label                               TEXT                ,                     -- The individual's name.
  sort_order                          INTEGER             ,                     -- Position in the cast.
  reasoning                           TEXT                ,                     -- The world this individual belongs to.
  portrait                            TEXT                ,                     -- The individual's picture.
  is_asserted_person                  BOOLEAN             ,                     -- Stated: this individual is a Person (isA Person).
  is_asserted_school                  BOOLEAN             ,                     -- Stated: this individual is a School (isA School).
  age                                 INTEGER             ,                     -- Stated: hasAge.
  attends                             TEXT                                      -- Stated: the place this individual attends (attends). Its range is School.
);
COMMENT ON TABLE individuals IS 'Every individual of the world (owl:Thing). What is said about one individual alone is a column of its row: its age, the place it attends, whether it is asserted to be a Person or a School. Its current grade level and role come from their records. Class membership is a formula, not a table, because it is concluded: no one stated that South Park Elementary is a School.';
COMMENT ON COLUMN individuals.individual_id IS 'Key of the individual.';
COMMENT ON COLUMN individuals.label IS 'The individual''s name.';
COMMENT ON COLUMN individuals.sort_order IS 'Position in the cast.';
COMMENT ON COLUMN individuals.reasoning IS 'The world this individual belongs to.';
COMMENT ON COLUMN individuals.portrait IS 'The individual''s picture.';
COMMENT ON COLUMN individuals.is_asserted_person IS 'Stated: this individual is a Person (isA Person).';
COMMENT ON COLUMN individuals.is_asserted_school IS 'Stated: this individual is a School (isA School).';
COMMENT ON COLUMN individuals.age IS 'Stated: hasAge.';
COMMENT ON COLUMN individuals.attends IS 'Stated: the place this individual attends (attends). Its range is School.';

-- ----------------------------------------------------------------------------
-- Parenthoods: One row per stated isParentOf fact. A person has many children and a child more than one parent, so the link is its own entity with two links to Individuals. The inverse rule's isChildOf is not stored: it is this row read from the child's end.
-- ----------------------------------------------------------------------------
CREATE TABLE parenthoods (
  parenthood_id                       TEXT                 PRIMARY KEY,         -- Key of the fact: subject|property|object, as her page names it.
  reasoning                           TEXT                ,                     -- The world this fact belongs to.
  parent                              TEXT                ,                     -- The parent (the subject of isParentOf).
  child                               TEXT                                      -- The child (the object of isParentOf).
);
COMMENT ON TABLE parenthoods IS 'One row per stated isParentOf fact. A person has many children and a child more than one parent, so the link is its own entity with two links to Individuals. The inverse rule''s isChildOf is not stored: it is this row read from the child''s end.';
COMMENT ON COLUMN parenthoods.parenthood_id IS 'Key of the fact: subject|property|object, as her page names it.';
COMMENT ON COLUMN parenthoods.reasoning IS 'The world this fact belongs to.';
COMMENT ON COLUMN parenthoods.parent IS 'The parent (the subject of isParentOf).';
COMMENT ON COLUMN parenthoods.child IS 'The child (the object of isParentOf).';

-- ----------------------------------------------------------------------------
-- Marriages: One row per stated isSpouseOf fact. A marriage has no direction: the symmetric rule is the same row counted from its second partner's end.
-- ----------------------------------------------------------------------------
CREATE TABLE marriages (
  marriage_id                         TEXT                 PRIMARY KEY,         -- Key of the fact: subject|property|object, as her page names it.
  reasoning                           TEXT                ,                     -- The world this fact belongs to.
  partner_a                           TEXT                ,                     -- The partner the stated fact names first.
  partner_b                           TEXT                                      -- The partner the stated fact names second.
);
COMMENT ON TABLE marriages IS 'One row per stated isSpouseOf fact. A marriage has no direction: the symmetric rule is the same row counted from its second partner''s end.';
COMMENT ON COLUMN marriages.marriage_id IS 'Key of the fact: subject|property|object, as her page names it.';
COMMENT ON COLUMN marriages.reasoning IS 'The world this fact belongs to.';
COMMENT ON COLUMN marriages.partner_a IS 'The partner the stated fact names first.';
COMMENT ON COLUMN marriages.partner_b IS 'The partner the stated fact names second.';

-- ----------------------------------------------------------------------------
-- Friendships: One row per stated isFriendOf fact, read both ways by the symmetric rule, like a marriage.
-- ----------------------------------------------------------------------------
CREATE TABLE friendships (
  friendship_id                       TEXT                 PRIMARY KEY,         -- Key of the fact: subject|property|object, as her page names it.
  reasoning                           TEXT                ,                     -- The world this fact belongs to.
  friend_a                            TEXT                ,                     -- The friend the stated fact names first.
  friend_b                            TEXT                                      -- The friend the stated fact names second.
);
COMMENT ON TABLE friendships IS 'One row per stated isFriendOf fact, read both ways by the symmetric rule, like a marriage.';
COMMENT ON COLUMN friendships.friendship_id IS 'Key of the fact: subject|property|object, as her page names it.';
COMMENT ON COLUMN friendships.reasoning IS 'The world this fact belongs to.';
COMMENT ON COLUMN friendships.friend_a IS 'The friend the stated fact names first.';
COMMENT ON COLUMN friendships.friend_b IS 'The friend the stated fact names second.';

-- ----------------------------------------------------------------------------
-- Grandparenthoods: The property chain isParentOf then isParentOf, as rows: every ordered pair of parenthoods is a candidate, and it holds when the first one's child is the second one's parent. A formula cannot add a row, so the candidates are data (every pair, decided by nothing about the family) and whether one holds is a formula.
-- ----------------------------------------------------------------------------
CREATE TABLE grandparenthoods (
  grandparenthood_id                  TEXT                 PRIMARY KEY,         -- Key: the upper parenthood, then the lower one.
  reasoning                           TEXT                ,                     -- The world this candidate belongs to.
  upper_link                          TEXT                ,                     -- The first link: grandparent to the middle generation.
  lower_link                          TEXT                                      -- The second link: the middle generation to the grandchild.
);
COMMENT ON TABLE grandparenthoods IS 'The property chain isParentOf then isParentOf, as rows: every ordered pair of parenthoods is a candidate, and it holds when the first one''s child is the second one''s parent. A formula cannot add a row, so the candidates are data (every pair, decided by nothing about the family) and whether one holds is a formula.';
COMMENT ON COLUMN grandparenthoods.grandparenthood_id IS 'Key: the upper parenthood, then the lower one.';
COMMENT ON COLUMN grandparenthoods.reasoning IS 'The world this candidate belongs to.';
COMMENT ON COLUMN grandparenthoods.upper_link IS 'The first link: grandparent to the middle generation.';
COMMENT ON COLUMN grandparenthoods.lower_link IS 'The second link: the middle generation to the grandchild.';

-- ----------------------------------------------------------------------------
-- GradeLevelRecords: Every grade level stated for an individual, kept when a later one replaces it: her page keeps one current grade, the latest switched on. The current value is time (which was stated last), not a flag.
-- ----------------------------------------------------------------------------
CREATE TABLE grade_level_records (
  grade_level_record_id               TEXT                 PRIMARY KEY,         -- Key: individual|grade|when it was stated.
  reasoning                           TEXT                ,                     -- The world this record belongs to.
  individual                          TEXT                ,                     -- Whose value it is.
  grade_level                         INTEGER             ,                     -- The value stated.
  stated_seq                          INTEGER             ,                     -- When the value was switched on, in the order facts are stated (transaction time). The latest one switched on is in effect.
  is_on                               BOOLEAN                                   -- The value is switched on. A value switched off stays in the record.
);
COMMENT ON TABLE grade_level_records IS 'Every grade level stated for an individual, kept when a later one replaces it: her page keeps one current grade, the latest switched on. The current value is time (which was stated last), not a flag.';
COMMENT ON COLUMN grade_level_records.grade_level_record_id IS 'Key: individual|grade|when it was stated.';
COMMENT ON COLUMN grade_level_records.reasoning IS 'The world this record belongs to.';
COMMENT ON COLUMN grade_level_records.individual IS 'Whose value it is.';
COMMENT ON COLUMN grade_level_records.grade_level IS 'The value stated.';
COMMENT ON COLUMN grade_level_records.stated_seq IS 'When the value was switched on, in the order facts are stated (transaction time). The latest one switched on is in effect.';
COMMENT ON COLUMN grade_level_records.is_on IS 'The value is switched on. A value switched off stays in the record.';

-- ----------------------------------------------------------------------------
-- RoleRecords: Every role stated for an individual; the latest one switched on is in effect, like a grade level.
-- ----------------------------------------------------------------------------
CREATE TABLE role_records (
  role_record_id                      TEXT                 PRIMARY KEY,         -- Key: individual|role|when it was stated.
  reasoning                           TEXT                ,                     -- The world this record belongs to.
  individual                          TEXT                ,                     -- Whose value it is.
  role                                TEXT                ,                     -- The value stated.
  stated_seq                          INTEGER             ,                     -- When the value was switched on, in the order facts are stated (transaction time). The latest one switched on is in effect.
  is_on                               BOOLEAN                                   -- The value is switched on. A value switched off stays in the record.
);
COMMENT ON TABLE role_records IS 'Every role stated for an individual; the latest one switched on is in effect, like a grade level.';
COMMENT ON COLUMN role_records.role_record_id IS 'Key: individual|role|when it was stated.';
COMMENT ON COLUMN role_records.reasoning IS 'The world this record belongs to.';
COMMENT ON COLUMN role_records.individual IS 'Whose value it is.';
COMMENT ON COLUMN role_records.role IS 'The value stated.';
COMMENT ON COLUMN role_records.stated_seq IS 'When the value was switched on, in the order facts are stated (transaction time). The latest one switched on is in effect.';
COMMENT ON COLUMN role_records.is_on IS 'The value is switched on. A value switched off stays in the record.';

